const crypto=require('crypto');
const headers=$json.headers||{}; const raw=String($json.rawBody||''); const ts=String(headers['x-slack-request-timestamp']||''); const sig=String(headers['x-slack-signature']||'');
const secret=String($env.SUPPORTPORTAL_SLACK_SIGNING_SECRET||''); const age=Math.abs(Math.floor(Date.now()/1000)-Number(ts||0));
const expected='v0='+crypto.createHmac('sha256',secret).update(`v0:${ts}:${raw}`).digest('hex');
if(!secret||age>300||sig.length!==expected.length||!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(expected))) throw new Error('invalid_slack_signature');
const body=typeof $json.body==='object'?$json.body:JSON.parse(raw); if(body.type==='url_verification') return [{json:{ack:{challenge:body.challenge},eligible:false}}];
const e=body.event||{}; const text=String(e.text||''); const cleaned=text.replace(/<@REPLACE_WITH_SLACK_BOT_USER_ID>/g,'').trim();
const eligible=String(body.team_id||'')==='REPLACE_WITH_SLACK_TEAM_ID' && String(e.channel||'')==='REPLACE_WITH_SLACK_CHANNEL_ID' && String(e.type||'')==='app_mention' && !!String(e.thread_ts||'') && !e.bot_id && !e.subtype && !e.edited && !e.deleted_ts && !!cleaned;
return [{json:{ack:{ok:true},eligible,event_id:String(body.event_id||''),team_id:String(body.team_id||''),channel_id:String(e.channel||''),thread_ts:String(e.thread_ts||''),slack_user_id:String(e.user||''),text:cleaned,occurred_at:String(e.event_ts||'')}}];
